class Solution {
    public int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (n & 1);
            n >>>= 1;
        }
        return result;
    }
}

class Solution {
    private static final int[] BYTE_REVERSE = buildTable();

    public int reverseBits(int n) {
        return (BYTE_REVERSE[n & 0xff] << 24)
                | (BYTE_REVERSE[(n >>> 8) & 0xff] << 16)
                | (BYTE_REVERSE[(n >>> 16) & 0xff] << 8)
                | BYTE_REVERSE[(n >>> 24) & 0xff];
    }

    private static int[] buildTable() {
        int[] table = new int[256];
        for (int value = 0; value < table.length; value++) {
            int x = value;
            int reversed = 0;
            for (int i = 0; i < 8; i++) {
                reversed = (reversed << 1) | (x & 1);
                x >>>= 1;
            }
            table[value] = reversed;
        }
        return table;
    }
}

class Solution {
    public int reverseBits(int n) {
        int result = 0;
        int sourceMask = 1;
        int targetMask = 1 << 31;
        for (int i = 0; i < 32; i++) {
            if ((n & sourceMask) != 0) {
                result |= targetMask;
            }
            sourceMask <<= 1;
            targetMask >>>= 1;
        }
        return result;
    }
}

class Solution {
    public int reverseBits(int n) {
        return reverse(n, 32);
    }

    private int reverse(int value, int width) {
        if (width == 1) {
            return value & 1;
        }
        int half = width >>> 1;
        int mask = (1 << half) - 1;
        int low = value & mask;
        int high = value >>> half;
        return (reverse(low, half) << half) | reverse(high, half);
    }
}
